	// Matrix multiplication in min-plus
	func matMul(A, B [][]int64) [][]int64 {
		size := len(A)
		C := make([][]int64, size)
		for i := range C {
			C[i] = make([]int64, size)
			for j := range C[i] {
				C[i][j] = INF
			}
		}
		for i := 0; i < size; i++ {
			for k := 0; k < size; k++ {
				if A[i][k] == INF {
					continue
				}
				for j := 0; j < size; j++ {
					if B[k][j] == INF {
						continue
					}
					val := A[i][k] + B[k][j]
					if val < C[i][j] {
						C[i][j] = val
					}
				}
			}
		}
		return C
	}

	// Identity matrix in min-plus: I[i][j] = 0 if i==j, else INF
	I := make([][]int64, n+1)
	for i := range I {
		I[i] = make([]int64, n+1)
		for j := range I[i] {
			if i == j {
				I[i][j] = 0
			} else {
				I[i][j] = INF
			}
		}
	}

